import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState([]);
  const [result, setResult] = useState(null);

  // ================= CAMÉRA START =================
  useEffect(() => {
    const startCamera = async () => {
      try {
        pushStatus("🎥 Démarrage de la caméra...");

        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });

        streamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }

        pushStatus("✅ Caméra démarrée avec succès");

      } catch (err) {
        console.error(err);
        pushStatus("❌ Impossible d'accéder à la caméra");
      }
    };

    startCamera();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  // ================= HELPERS =================
  const pushStatus = (msg) => {
    setStatus(prev => [...prev, msg]);
  };

  const resetStatus = () => {
    setStatus([]);
  };

  // ================= STOP CAMÉRA =================
  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    pushStatus("📴 Caméra arrêtée");
  };

  // ================= CAPTURE + RECO =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    resetStatus();
    setResult(null);

    try {
      // STEP 1
      pushStatus("📸 Étape 1/4 : Capture de l'image...");

      const canvas = document.createElement("canvas");
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext("2d");
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL("image/jpeg", 0.92);

      // STEP 2
      pushStatus("🚀 Étape 2/4 : Envoi de l'image au Backend...");

      const response = await attendanceAPI.recognize(imageSrc);

      // STEP 3
      pushStatus("📥 Étape 3/4 : Réponse reçue du Backend...");

      const data = response?.data || response || {};

      const name =
        data.student ||
        data.student_name ||
        data.name ||
        "Inconnu";

      const confidence = Number(data.confidence || 0);

      // STEP 4
      if (data.success || confidence > 0) {
        pushStatus(
          `✅ Étape 4/4 : Succès ! ${name} - ${(confidence * 100).toFixed(1)}%`
        );

        setResult({
          name,
          confidence: (confidence * 100).toFixed(1),
          studentId: data.student_id || "N/A",
          time: new Date().toLocaleTimeString()
        });

      } else {
        pushStatus("⚠️ Étape 4/4 : No face detected or low quality");
      }

    } catch (err) {
      const msg =
        err?.response?.data?.error ||
        err?.message ||
        "Erreur serveur";

      pushStatus(`❌ Étape 4/4 : ${msg}`);
    } finally {
      setLoading(false);
    }
  }, []);

  // ================= UI =================
  return (
    <div style={{ padding: 30, maxWidth: 850, margin: "auto", textAlign: "center" }}>

      <h2>📷 Reconnaissance Faciale</h2>

      {/* CAMERA */}
      <div style={{
        background: "#000",
        borderRadius: 12,
        overflow: "hidden",
        marginBottom: 20
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: "100%" }}
        />
      </div>

      {/* BUTTONS */}
      <div style={{ display: "flex", gap: 10 }}>
        <button
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: 15,
            background: loading ? "#999" : "#4F46E5",
            color: "white",
            border: 0,
            borderRadius: 10,
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "⏳ Analyse..." : "🔍 Capturer & Analyser"}
        </button>

        <button
          onClick={stopCamera}
          style={{
            flex: 1,
            padding: 15,
            background: "#EF4444",
            color: "white",
            border: 0,
            borderRadius: 10
          }}
        >
          🛑 Stop
        </button>
      </div>

      {/* STATUS LIST (IMPORTANT FIX) */}
      <div style={{
        marginTop: 20,
        padding: 15,
        borderRadius: 10,
        background: "#F3F4F6",
        textAlign: "left"
      }}>
        {status.map((s, i) => (
          <div key={i} style={{ marginBottom: 6 }}>
            {s}
          </div>
        ))}
      </div>

      {/* RESULT */}
      {result && (
        <div style={{
          marginTop: 20,
          padding: 15,
          background: "#E0E7FF",
          borderRadius: 10,
          textAlign: "left"
        }}>
          <p><b>👤 Nom:</b> {result.name}</p>
          <p><b>🎯 Confiance:</b> {result.confidence}%</p>
          <p><b>🆔 ID:</b> {result.studentId}</p>
          <p><b>🕒 Heure:</b> {result.time}</p>
        </div>
      )}

    </div>
  );
};

export default CameraRecognition;
